    const n = matchers(actual, true);
    n.toThrowError = n.toThrow;
    m.not = guard(n);
    return guard(m);
  };
})();


test("odd length", () => {
  expect(median([3, 1, 2])).toBe(2);
});

test("even length", () => {
  expect(median([4, 1, 3, 2])).toBe(2.5);
});

test("empty list", () => {
  expect(median([])).toBe(0);
}, { silentOn: "what the median of nothing is", reasonable: "NaN (nothing to take the middle of) and throwing are also defensible." });

